mapper.update:
UPDATE agent_conversation_elicitation
SET status = #{status},
    answer_json = #{answerJson},
    gmt_modified = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND request_id = #{requestId}
  AND status = 'PENDING'

UPDATE agent_conversation_elicitation
SET status = 'PENDING',
    answer_json = NULL,
    gmt_modified = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND request_id = #{requestId}
  AND status = #{expectedStatus}

mapper.select:
SELECT  FROM agent_conversation_elicitation
WHERE status = 'PENDING' AND id > #{afterId}
  AND gmt_create < #{cutoff}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE agent_conversation_elicitation
SET status = #{status}, answer_json = #{answerJson}, answer_id = #{answerId},
    delivery_status = 'SAVED', delivery_deadline = #{deliveryDeadline},
    next_delivery_at = #{nextDeliveryAt}, gmt_modified = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
  AND request_id = #{requestId} AND status = 'PENDING'
  AND answer_protocol_version = 1 AND dispatch_attempt = #{dispatchAttempt}
  AND executor_id = #{executorId}

mapper.select:
SELECT  FROM agent_conversation_elicitation
WHERE status IN ('ANSWERED','DECLINED')
  AND delivery_status IN ('SAVED','RECEIVED','UNKNOWN','UNAVAILABLE') AND next_delivery_at <= #{now}
ORDER BY next_delivery_at, id LIMIT #{limit}

mapper.update:
UPDATE agent_conversation_elicitation SET next_delivery_at = #{next}
WHERE id = #{id} AND status IN ('ANSWERED','DECLINED')
  AND delivery_status IN ('SAVED','RECEIVED','UNKNOWN','UNAVAILABLE') AND next_delivery_at <= #{now}

