SELECT * FROM (
    SELECT  FROM agent_conversation_elicitation
    WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
    ORDER BY id DESC LIMIT 100
) recent WHERE answer_id IS NOT NULL AND status IN ('ANSWERED','DECLINED') ORDER BY id DESC

