UPDATE agent_conversation_elicitation SET delivery_status = 'UNKNOWN', next_delivery_at = NULL, gmt_modified = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId} AND turn_id = #{turnId}
  AND delivery_status IN ('SAVED','RECEIVED')

UPDATE agent_conversation_elicitation SET next_delivery_at = NULL
WHERE tenant_id = #{tenantId} AND executor_id = #{executorId} AND conversation_id = #{conversationId}
  AND turn_id = #{turnId} AND dispatch_attempt = #{attempt}
  AND delivery_status IN ('UNKNOWN','UNAVAILABLE')
